from html.parser import HTMLParser
from pathlib import Path
import re
class Audit(HTMLParser):
    def __init__(self):
        super().__init__(); self.ids=[]; self.links=[]; self.scripts=[]; self.in_script=False; self.details=0; self.images=[]; self.headings=[]; self.in_heading=False
    def handle_starttag(self, tag, attrs):
        a=dict(attrs)
        if 'id' in a:self.ids.append(a['id'])
        if tag=='a':self.links.append(a.get('href',''))
        if tag=='details':self.details+=1
        if tag=='img':self.images.append(a.get('src',''))
        if tag=='script':self.in_script=True
    def handle_endtag(self, tag):
        if tag=='script':self.in_script=False
    def handle_data(self, data):
        if self.in_script:self.scripts.append(data)
s=Path('index.html').read_text(); p=Audit(); p.feed(s)
assert len(p.ids)==len(set(p.ids)), 'Duplicate IDs'
assert p.details==5
assert not p.images
for href in p.links:
    if href.startswith('#') and len(href)>1:assert href[1:] in p.ids, href
for text in ['Know who\\'s on call.', 'Hand off without losing the thread.', '38%', '4 min', '2,100', '99.95%', '© 2026 Rotaline, Inc.']:
    assert text in s, text
Path('/private/tmp/rotaline-script.js').write_text('\\n'.join(p.scripts))
print('HTML checks passed: 5 FAQs, unique IDs, valid section links, inline visuals, required headline and figures.')
